function check(candidate) {
    console.assert(JSON.stringify(candidate([0,1,1,0,1,1,0,0])) === JSON.stringify(8));
    console.assert(JSON.stringify(candidate([1,0,0,1,0,1,1])) === JSON.stringify(6));
